"""Capture the exact tested bounded candidate, without publication or GPU claims."""
from pathlib import Path
import hashlib,json,datetime,subprocess
R=Path(__file__).resolve().parents[1];H=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
subprocess.run(['node','tests/v16-1-scope.test.mjs'],cwd=R/'web',check=True)
paths=[R/'web/index.html']+[p for d in ['web/src','web/public'] for p in(R/d).rglob('*')if p.is_file()]
rows=[{'path':p.relative_to(R).as_posix(),'bytes':p.stat().st_size,'sha256':H(p)}for p in sorted(paths)]
gate=json.loads((R/'tests/v16_1/final_gate_receipt.json').read_text());assert gate['result']=='PASS'and gate['runtime_unchanged_during_gate']
assert{x['path']:x['sha256']for x in rows}==gate['runtime_hashes']
tree=hashlib.sha256(''.join(x['path']+'\0'+x['sha256']+'\n'for x in sorted(rows,key=lambda x:x['path'])).encode()).hexdigest()
anchors=['dist/malabar-hot-coast.html','dist/game.bundle.js','dist/ui-preview.html','dist/v16-1-ui-preview.html','dist/v16-1-ui-frame.html','web/package.json','web/package-lock.json','web/build-standalone.mjs','web/build-ui-preview.mjs','web/build-render-review-frame.mjs','tests/v16_1/full_gate.log','tests/v16_1/final_gate_receipt.json','tests/recovery/standalone_integrity.json','docs/v16_1/BROWSER_ACCEPTANCE_PLAN.md','docs/v16_1/SCOPE.md']
report={'candidate':'MALABAR V16.1 bounded render diagnostics/contrast correction','created_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'base':'V16 Sites33 commit f5e6ef0a0d1252b59528319c988cbc97172e1e52','runtime_tree_sha256':tree,'tree_algorithm':'SHA256 of sorted relative-path + NUL + file SHA256 + newline','runtime_files':rows,'anchors':{n:{'bytes':(R/n).stat().st_size,'sha256':H(R/n)}for n in anchors},'protected':'138 V16 runtime files byte-identical, including all assets, contact/physics, rewards, saves, audio, Story and camera helpers. Default Auto DPR unchanged.','scope':['Late opaque depth-tested sky without shader/detail changes','Session-only Full/Standard/Auto resolution comparison independent of quality','Actual buffer/DPR/MSAA/shadow diagnostics and resettable five-active-second RAF windows','Surface-only route/status contrast; redundant no-pursuit label hidden'],'limits':['No measured native FPS improvement or GPU visual acceptance yet','RAF timings include application/capture overhead, not GPU-only timings','Preview screenshots use synthetic background/state, not live gameplay'],'license':'Genuine OSM/Three/font notices retained; no new original-material reuse grant; no private reference images.'}
(R/'tests/release/V16_1_RELEASE.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps({'runtime_files':len(rows),'runtime_tree_sha256':tree,'standalone':report['anchors']['dist/malabar-hot-coast.html']},indent=2))
